-- Anonymous quiz completion events, extended so the landing page can show
-- aggregate stats.
--
-- One row per completed quiz. `session_id` is generated by the client for each
-- completed run and is unique, which makes POST /api/quiz/events idempotent:
-- a retry (or a restored results view) cannot inflate the counters. Legacy rows
-- and rows inserted without a session keep working, because SQLite allows
-- multiple NULLs in a UNIQUE index.
--
-- No identifiers, IPs or free text are stored -- only the quiz outcome.

ALTER TABLE quiz_events ADD COLUMN session_id TEXT;
ALTER TABLE quiz_events ADD COLUMN answered_count INTEGER;
ALTER TABLE quiz_events ADD COLUMN top_match_name TEXT;
ALTER TABLE quiz_events ADD COLUMN top_match_score REAL;
ALTER TABLE quiz_events ADD COLUMN user_tolerance INTEGER;
ALTER TABLE quiz_events ADD COLUMN user_certainty INTEGER;

CREATE UNIQUE INDEX IF NOT EXISTS idx_quiz_events_session ON quiz_events (session_id);
CREATE INDEX IF NOT EXISTS idx_quiz_events_created ON quiz_events (created_at);
